"""Exceptions for minisql."""


class QueryError(Exception):
    """Raised for any problem with a query."""

"""AST node types shared by the parser and the execution engine.

The parser must fill ``text`` on every expression node with the exact slice of
the query source that produced that node.  Output column names fall back to
this text, so it must not be normalised (beyond excluding surrounding
whitespace).
"""

from dataclasses import dataclass, field
from typing import Any, List, Optional


AGGREGATES = frozenset({"COUNT", "SUM", "AVG", "MIN", "MAX"})


@dataclass
class Literal:
    """A literal value: int, float, str, bool, or None for NULL."""

    text: str
    value: Any


@dataclass
class Column:
    """A reference to a table column.  ``name`` is unescaped as written."""

    text: str
    name: str


@dataclass
class Star:
    """``*`` in a select list or inside COUNT(*)."""

    text: str


@dataclass
class Paren:
    """A parenthesised expression; kept so its source text is preserved."""

    text: str
    operand: Any


@dataclass
class Unary:
    """Unary ``-`` or ``NOT``."""

    text: str
    op: str
    operand: Any


@dataclass
class Binary:
    """Arithmetic, concatenation, or boolean connective.

    ``op`` is one of ``+ - * / || AND OR``.
    """

    text: str
    op: str
    left: Any
    right: Any


@dataclass
class Compare:
    """Comparison; ``op`` is one of ``= != < <= > >=`` (``<>`` normalised)."""

    text: str
    op: str
    left: Any
    right: Any


@dataclass
class IsNull:
    text: str
    operand: Any
    negated: bool


@dataclass
class InList:
    text: str
    operand: Any
    items: List[Any] = field(default_factory=list)
    negated: bool = False


@dataclass
class Between:
    text: str
    operand: Any
    low: Any
    high: Any
    negated: bool = False


@dataclass
class Like:
    text: str
    operand: Any
    pattern: Any
    negated: bool = False


@dataclass
class Func:
    """A scalar or aggregate function call.  ``name`` is upper-cased.

    ``star`` is true for ``COUNT(*)`` only.
    """

    text: str
    name: str
    args: List[Any] = field(default_factory=list)
    star: bool = False


@dataclass
class SelectItem:
    expr: Any
    alias: Optional[str] = None


@dataclass
class OrderItem:
    expr: Any
    desc: bool = False


@dataclass
class Query:
    distinct: bool
    star: bool
    items: List[SelectItem]
    table: str
    where: Any = None
    group_by: List[Any] = field(default_factory=list)
    having: Any = None
    order_by: List[OrderItem] = field(default_factory=list)
    limit: Optional[int] = None
    offset: Optional[int] = None


def children(expr):
    """Yield the direct sub-expressions of an expression node."""
    if isinstance(expr, (Literal, Column, Star)):
        return
    if isinstance(expr, Paren):
        yield expr.operand
    elif isinstance(expr, (Unary,)):
        yield expr.operand
    elif isinstance(expr, IsNull):
        yield expr.operand
    elif isinstance(expr, Binary) or isinstance(expr, Compare):
        yield expr.left
        yield expr.right
    elif isinstance(expr, InList):
        yield expr.operand
        yield from expr.items
    elif isinstance(expr, Between):
        yield expr.operand
        yield expr.low
        yield expr.high
    elif isinstance(expr, Like):
        yield expr.operand
        yield expr.pattern
    elif isinstance(expr, Func):
        yield from expr.args


def walk(expr):
    """Yield ``expr`` and all of its sub-expressions, pre-order."""
    yield expr
    for child in children(expr):
        yield from walk(child)


def contains_aggregate(expr):
    return any(
        isinstance(node, Func) and node.name in AGGREGATES for node in walk(expr)
    )


def expr_key(expr):
    """A structural key used to decide whether two expressions are the same.

    Source text and whitespace are ignored, and column/function names are
    case-folded, mirroring SQL's case-insensitive name matching.
    """
    if isinstance(expr, Literal):
        # Keep bool distinct from 1; values of different types never compare
        # equal under the semantics, so type is part of the key.
        return ("lit", type(expr.value).__name__, expr.value)
    if isinstance(expr, Column):
        return ("col", expr.name.lower())
    if isinstance(expr, Star):
        return ("star",)
    if isinstance(expr, Paren):
        return expr_key(expr.operand)
    if isinstance(expr, Unary):
        return ("un", expr.op, expr_key(expr.operand))
    if isinstance(expr, Binary):
        return ("bin", expr.op, expr_key(expr.left), expr_key(expr.right))
    if isinstance(expr, Compare):
        return ("cmp", expr.op, expr_key(expr.left), expr_key(expr.right))
    if isinstance(expr, IsNull):
        return ("isnull", expr.negated, expr_key(expr.operand))
    if isinstance(expr, InList):
        return (
            "in",
            expr.negated,
            expr_key(expr.operand),
            tuple(expr_key(item) for item in expr.items),
        )
    if isinstance(expr, Between):
        return (
            "between",
            expr.negated,
            expr_key(expr.operand),
            expr_key(expr.low),
            expr_key(expr.high),
        )
    if isinstance(expr, Like):
        return (
            "like",
            expr.negated,
            expr_key(expr.operand),
            expr_key(expr.pattern),
        )
    if isinstance(expr, Func):
        return (
            "func",
            expr.name.upper(),
            expr.star,
            tuple(expr_key(arg) for arg in expr.args),
        )
    raise AssertionError("unknown expression node: %r" % (expr,))

"""Query execution for minisql."""

import csv
import functools
import os

from . import ast
from .errors import QueryError
from .parser import parse
from . import values


# Function name -> (minimum arguments, maximum arguments or None).
SCALAR_ARITIES = {
    "LOWER": (1, 1),
    "UPPER": (1, 1),
    "LENGTH": (1, 1),
    "ABS": (1, 1),
    "ROUND": (1, 2),
    "COALESCE": (1, None),
}


class Result:
    """The outcome of :func:`minisql.run`."""

    __slots__ = ("columns", "rows")

    def __init__(self, columns, rows):
        self.columns = list(columns)
        self.rows = list(rows)

    def __eq__(self, other):
        if not isinstance(other, Result):
            return NotImplemented
        return self.columns == other.columns and self.rows == other.rows

    def __repr__(self):
        return "Result(columns=%r, rows=%r)" % (self.columns, self.rows)


class _Table:
    __slots__ = ("columns", "rows", "lookup")

    def __init__(self, columns, rows):
        self.columns = columns
        self.rows = rows
        self.lookup = {}
        for index, name in enumerate(columns):
            self.lookup.setdefault(name.lower(), index)


class _Engine:
    def __init__(self, query, directory):
        self.query = query
        self.directory = directory
        self.table = None
        self.output_exprs = []
        self.output_names = []

    # -- setup -----------------------------------------------------------

    def execute(self):
        query = self.query
        self.table = self._load_table(query.table)
        self._prepare_output()

        # Static checks that do not depend on any data.
        for expr in self.output_exprs:
            self._check_expression(expr)
        if query.where is not None:
            self._check_expression(query.where)
            if ast.contains_aggregate(query.where):
                raise QueryError("aggregates are not allowed in WHERE")
        for expr in query.group_by:
            self._check_expression(expr)
            if ast.contains_aggregate(expr):
                raise QueryError("aggregates are not allowed in GROUP BY")
        if query.having is not None:
            self._check_expression(query.having)
        for item in query.order_by:
            if self._order_target(item.expr) is None:
                self._check_expression(item.expr)

        grouped = self._is_grouped()
        if grouped:
            keys = {ast.expr_key(expr) for expr in query.group_by}
            for expr in self.output_exprs:
                self._check_grouped(expr, keys)
            if query.having is not None:
                self._check_grouped(query.having, keys)
            for item in query.order_by:
                if self._order_target(item.expr) is None:
                    self._check_grouped(item.expr, keys)

        return self._run(grouped)

    def _load_table(self, name):
        path = os.path.join(self.directory, name + ".csv")
        try:
            with open(path, "r", newline="", encoding="utf-8") as handle:
                reader = csv.reader(handle)
                try:
                    header = next(reader)
                except StopIteration:
                    raise QueryError("table %r is empty" % name) from None
                columns = list(header)
                width = len(columns)
                rows = []
                try:
                    for raw in reader:
                        row = [
                            values.parse_field(field) for field in raw[:width]
                        ]
                        if len(row) < width:
                            row.extend([None] * (width - len(row)))
                        rows.append(row)
                except csv.Error as exc:
                    raise QueryError(
                        "could not read table %r: %s" % (name, exc)
                    ) from None
        except FileNotFoundError:
            raise QueryError("unknown table: %s" % name) from None
        except IsADirectoryError:
            raise QueryError("unknown table: %s" % name) from None
        except OSError as exc:
            raise QueryError(
                "could not read table %r: %s" % (name, exc)
            ) from None
        except UnicodeDecodeError as exc:
            raise QueryError(
                "could not read table %r: %s" % (name, exc)
            ) from None
        return _Table(columns, rows)

    def _prepare_output(self):
        query = self.query
        if query.star:
            self.output_exprs = [
                ast.Column(name, name) for name in self.table.columns
            ]
            self.output_names = list(self.table.columns)
            return

        for item in query.items:
            self.output_exprs.append(item.expr)
            if item.alias is not None:
                self.output_names.append(item.alias)
            elif isinstance(item.expr, ast.Column):
                index = self.table.lookup.get(item.expr.name.lower())
                if index is None:
                    # Reported by _check_expression with a consistent message.
                    self.output_names.append(item.expr.name)
                else:
                    self.output_names.append(self.table.columns[index])
            else:
                self.output_names.append(item.expr.text)

    # -- static validation ----------------------------------------------

    def _column_index(self, name):
        index = self.table.lookup.get(name.lower())
        if index is None:
            raise QueryError("unknown column: %s" % name)
        return index

    def _check_expression(self, expr):
        """Validate column references and function usage recursively."""
        for node in ast.walk(expr):
            if isinstance(node, ast.Column):
                self._column_index(node.name)
            elif isinstance(node, ast.Star):
                raise QueryError("* is only allowed in the select list or COUNT(*)")
            elif isinstance(node, ast.Func):
                self._check_function(node)
                if node.name in ast.AGGREGATES:
                    for arg in node.args:
                        if ast.contains_aggregate(arg):
                            raise QueryError(
                                "aggregates cannot be nested"
                            )

    def _check_function(self, node):
        name = node.name
        if node.star:
            if name != "COUNT":
                raise QueryError(
                    "* is only allowed in COUNT(*), not %s(*)" % name
                )
            return
        if name in ast.AGGREGATES:
            if len(node.args) != 1:
                raise QueryError(
                    "%s expects 1 argument, got %d"
                    % (name, len(node.args))
                )
            return
        if name not in SCALAR_ARITIES:
            raise QueryError("unknown function: %s" % name)
        minimum, maximum = SCALAR_ARITIES[name]
        count = len(node.args)
        if count < minimum or (maximum is not None and count > maximum):
            if maximum is None:
                expected = "at least %d argument%s" % (
                    minimum,
                    "" if minimum == 1 else "s",
                )
            elif minimum == maximum:
                expected = "%d argument%s" % (
                    minimum,
                    "" if minimum == 1 else "s",
                )
            else:
                expected = "%d or %d arguments" % (minimum, maximum)
            raise QueryError(
                "%s expects %s, got %d" % (name, expected, count)
            )

    def _check_grouped(self, expr, keys):
        """Every column outside an aggregate must be grouped over."""
        if ast.expr_key(expr) in keys:
            return
        if isinstance(expr, ast.Func) and expr.name in ast.AGGREGATES:
            return
        if isinstance(expr, ast.Column):
            raise QueryError(
                "column %s must appear in GROUP BY or be used in an "
                "aggregate" % expr.name
            )
        for child in ast.children(expr):
            self._check_grouped(child, keys)

    def _is_grouped(self):
        query = self.query
        if query.group_by:
            return True
        expressions = [item.expr for item in query.items]
        if query.having is not None:
            expressions.append(query.having)
        expressions.extend(item.expr for item in query.order_by)
        return any(ast.contains_aggregate(expr) for expr in expressions)

    # -- evaluation ------------------------------------------------------

    def _eval(self, expr, row, group_rows=None):
        if isinstance(expr, ast.Literal):
            return expr.value
        if isinstance(expr, ast.Column):
            return row[self._column_index(expr.name)]
        if isinstance(expr, ast.Paren):
            return self._eval(expr.operand, row, group_rows)
        if isinstance(expr, ast.Star):
            raise QueryError(
                "* is only allowed in the select list or COUNT(*)"
            )
        if isinstance(expr, ast.Unary):
            operand = self._eval(expr.operand, row, group_rows)
            if expr.op == "-":
                return values.negate(operand)
            return values.not3(operand)
        if isinstance(expr, ast.Binary):
            left = self._eval(expr.left, row, group_rows)
            right = self._eval(expr.right, row, group_rows)
            if expr.op == "AND":
                return values.and3(left, right)
            if expr.op == "OR":
                return values.or3(left, right)
            if expr.op == "||":
                return values.concat(left, right)
            return values.arithmetic(expr.op, left, right)
        if isinstance(expr, ast.Compare):
            left = self._eval(expr.left, row, group_rows)
            right = self._eval(expr.right, row, group_rows)
            return values.compare(expr.op, left, right)
        if isinstance(expr, ast.IsNull):
            result = self._eval(expr.operand, row, group_rows) is None
            return not result if expr.negated else result
        if isinstance(expr, ast.InList):
            operand = self._eval(expr.operand, row, group_rows)
            items = [
                self._eval(item, row, group_rows) for item in expr.items
            ]
            result = values.in_list(operand, items)
            return values.not3(result) if expr.negated else result
        if isinstance(expr, ast.Between):
            operand = self._eval(expr.operand, row, group_rows)
            low = self._eval(expr.low, row, group_rows)
            high = self._eval(expr.high, row, group_rows)
            result = values.and3(
                values.compare("<=", low, operand),
                values.compare("<=", operand, high),
            )
            return values.not3(result) if expr.negated else result
        if isinstance(expr, ast.Like):
            operand = self._eval(expr.operand, row, group_rows)
            pattern = self._eval(expr.pattern, row, group_rows)
            result = values.like(operand, pattern)
            return values.not3(result) if expr.negated else result
        if isinstance(expr, ast.Func):
            if expr.name in ast.AGGREGATES:
                if group_rows is None:
                    raise QueryError(
                        "aggregate %s is not allowed here" % expr.name
                    )
                return self._eval_aggregate(expr, group_rows)
            args = [
                self._eval(arg, row, group_rows) for arg in expr.args
            ]
            return values.scalar(expr.name, args)
        raise QueryError("unsupported expression")

    def _eval_aggregate(self, func, rows):
        name = func.name

        if func.star:
            # Only COUNT(*) reaches here; _check_function rejects the rest.
            if name != "COUNT":
                raise QueryError(
                    "* is only allowed in COUNT(*), not %s(*)" % name
                )
            return len(rows)

        if name == "COUNT":
            return sum(
                1
                for row in rows
                if self._eval(func.args[0], row) is not None
            )

        collected = []
        for row in rows:
            value = self._eval(func.args[0], row)
            if value is None:
                continue
            if name in ("SUM", "AVG") and not values.is_number(value):
                raise QueryError(
                    "%s requires numeric values, found %s"
                    % (name, values.type_name(value))
                )
            collected.append(value)

        if not collected:
            return None

        if name == "SUM":
            total = 0
            for value in collected:
                total = values.arithmetic("+", total, value)
            return total
        if name == "AVG":
            total = 0
            for value in collected:
                total = values.arithmetic("+", total, value)
            return values.arithmetic("/", total, len(collected))

        best = collected[0]
        for value in collected[1:]:
            if name == "MIN":
                if values.compare("<", value, best):
                    best = value
            else:
                if values.compare(">", value, best):
                    best = value
        return best

    def _order_target(self, expr):
        """Return an output index if this ORDER BY item names one."""
        if isinstance(expr, ast.Literal):
            if isinstance(expr.value, int) and not isinstance(
                expr.value, bool
            ):
                position = expr.value
                if position < 1 or position > len(self.output_exprs):
                    raise QueryError(
                        "ORDER BY position %d is out of range" % position
                    )
                return position - 1
            return None
        if isinstance(expr, ast.Column):
            lowered = expr.name.lower()
            for index, name in enumerate(self.output_names):
                if name.lower() == lowered:
                    return index
        return None

    def _run(self, grouped):
        query = self.query
        table = self.table

        filtered = []
        for row in table.rows:
            if query.where is not None:
                if not values.truth(self._eval(query.where, row)):
                    continue
            else:
                if False:
                    pass
            if not grouped and query.having is not None:
                if not values.truth(self._eval(query.having, row)):
                    continue
            filtered.append(row)

        entries = []  # (output tuple, sort keys)
        if grouped:
            group_order = []
            groups = {}
            key_expressions = query.group_by
            if key_expressions:
                for row in filtered:
                    key = tuple(
                        values.value_key(self._eval(expr, row))
                        for expr in key_expressions
                    )
                    bucket = groups.get(key)
                    if bucket is None:
                        bucket = []
                        groups[key] = bucket
                        group_order.append(bucket)
                    bucket.append(row)
            else:
                # Without GROUP BY all rows (even none) form one group.
                group_order.append(filtered)

            for rows in group_order:
                if query.having is not None:
                    probe = rows[0] if rows else self._null_row()
                    if not values.truth(
                        self._eval(query.having, probe, rows)
                    ):
                        continue
                probe = rows[0] if rows else self._null_row()
                output = tuple(
                    self._eval(expr, probe, rows)
                    for expr in self.output_exprs
                )
                entries.append(
                    (output, self._sort_keys(output, probe, rows))
                )
        else:
            for row in filtered:
                output = tuple(
                    self._eval(expr, row) for expr in self.output_exprs
                )
                entries.append((output, self._sort_keys(output, row, None)))

        if query.distinct:
            seen = set()
            unique = []
            for output, keys in entries:
                marker = tuple(values.value_key(value) for value in output)
                if marker in seen:
                    continue
                seen.add(marker)
                unique.append((output, keys))
            entries = unique

        for item in reversed(query.order_by):
            target = self._order_target(item.expr)
            if target is not None:
                index = target
                comparator = functools.cmp_to_key(
                    lambda a, b: self._compare_nullable(
                        a[0][index], b[0][index], item.desc
                    )
                )
            else:
                index = None
                comparator = functools.cmp_to_key(
                    lambda a, b: self._compare_nullable(
                        a[1][len(a[1]) - 1] if False else None,
                        None,
                        item.desc,
                    )
                )
                # Build a comparator that pulls this item's key.  Keys are
                # stored per ORDER BY item in query order.
                position = query.order_by.index(item)
                comparator = functools.cmp_to_key(
                    lambda a, b, pos=position: self._compare_nullable(
                        a[1][pos], b[1][pos], item.desc
                    )
                )
            entries.sort(key=comparator)

        offset = query.offset or 0
        limit = query.limit
        if limit is None:
            selected = entries[offset:]
        else:
            selected = entries[offset : offset + limit]

        return Result(self.output_names, [row for row, _ in selected])

    def _null_row(self):
        return [None] * len(self.table.columns)

    def _sort_keys(self, output, row, group_rows):
        keys = []
        for item in self.query.order_by:
            target = self._order_target(item.expr)
            if target is not None:
                keys.append(output[target])
            else:
                keys.append(self._eval(item.expr, row, group_rows))
        return keys

    @staticmethod
    def _compare_nullable(left, right, descending):
        if left is None or right is None:
            if left is None and right is None:
                return 0
            if left is None:
                return 1 if descending else -1
            return -1 if descending else 1
        if values.compare("<", left, right):
            return 1 if descending else -1
        if values.compare(">", left, right):
            return -1 if descending else 1
        return 0


def run(sql, directory="."):
    """Run ``sql`` against the CSV files in ``directory``.

    Returns a :class:`Result` with ``columns`` and ``rows`` attributes.
    Raises :class:`minisql.QueryError` for any problem with the query.
    """
    if not isinstance(sql, str):
        raise QueryError("query must be a string")
    query = parse(sql)
    return _Engine(query, directory).execute()

